def row_px(pct):
    """1.2: Scale in % (0 = the smallest rows, 100 = the biggest) -> row height in px."""
    return int(round(ROW_MIN + (ROW_MAX - ROW_MIN) * max(0, min(100, pct)) / 100.0))


def row_percent(px):
    return int(round(100.0 * (max(ROW_MIN, min(ROW_MAX, px)) - ROW_MIN) / (ROW_MAX - ROW_MIN)))


