def migrate_names():
    """1.0: tagger_config.json -> tagdeck_config.json and tagger_debug.log -> tagdeck_debug.log, once (the
    settings are copied to config_backups first). Returns what was done, for the log."""
    done = []
    old_cfg = APP_DIR / "tagger_config.json"
    if old_cfg.exists() and not CONFIG_PATH.exists():
        try:
            bdir = APP_DIR / "config_backups"
            bdir.mkdir(exist_ok=True)
            shutil.copy2(old_cfg, bdir / ("tagger_config_%s.json" % datetime.now().strftime("%Y%m%d-%H%M%S")))
            old_cfg.rename(CONFIG_PATH)
            done.append("settings: tagger_config.json -> %s" % CONFIG_PATH.name)
        except Exception as e:
            done.append("settings NOT renamed (%s): tagger_config.json is used" % e)
    for ext in ("", ".1"):
        old_log = APP_DIR / ("tagger_debug.log" + ext)
        new_log = Path(str(LOG_PATH) + ext)
        if old_log.exists() and not new_log.exists():
            try:
                old_log.rename(new_log)
                done.append("log: %s -> %s" % (old_log.name, new_log.name))
            except Exception:
                pass
    return done


def setup_logging():
    log.setLevel(logging.DEBUG)
    try:
        h = logging.handlers.RotatingFileHandler(LOG_PATH, maxBytes=1_000_000, backupCount=1, encoding="utf-8")
        h.setFormatter(logging.Formatter("%(asctime)s %(levelname)-7s %(message)s"))
        log.addHandler(h)
    except Exception:
        pass

    def qt_handler(mode, ctx, msg):
        if "editing failed" in msg:
            return
        log.info("qt: %s", msg)
    qInstallMessageHandler(qt_handler)
    try:
        import PySide6
        log.info("start TagDeck %s | Python %s | PySide6 %s | numpy %s", APP_VERSION, sys.version.split()[0],
                 PySide6.__version__, getattr(np, "__version__", "missing"))
    except Exception:
        pass

