def control_keys(cfg):
    saved = cfg.get("shortcuts", {})
    taken = {QKeySequence(h["key"]).toString() for h in cfg.get("hotkeys", []) if h.get("key")}
    out = {}
    for cid, _, default in CONTROLS:
        if cid in saved:
            out[cid] = saved[cid]
        elif cid.startswith("cue_") and QKeySequence(default).toString() in taken:
            out[cid] = ""                     # a tag hotkey has this key already: the hot cue gets none
        else:
            out[cid] = default
    return out


# 0.9.14: chip colors = Serato's track colors as Serato shows them (7 x 3); new tags get a random one not
# used yet in their field (not the greys / white)
TAG_PALETTE = ["#993399", "#993377", "#993355", "#993333", "#995533", "#997733", "#999933",
               "#779933", "#559933", "#339933", "#339955", "#339977", "#339999", "#337799",
               "#335599", "#333399", "#553399", "#773399", "#555555", "#333333", "#FFFFFF"]
TAG_PLAIN = ("#555555", "#333333", "#FFFFFF")


def nearest_palette(hexc):
    c = QColor(hexc)
    return min(TAG_PALETTE, key=lambda h: (QColor(h).red() - c.red()) ** 2 + (QColor(h).green() - c.green()) ** 2 +
               (QColor(h).blue() - c.blue()) ** 2)


def chip_text_color(c):
    """Black text on light chips (yellow, white, cyan...), white on dark ones."""
    def lin(v):                                  # 1.2: real (WCAG) luminance: the text with more contrast wins
        v /= 255.0
        return v / 12.92 if v <= 0.03928 else ((v + 0.055) / 1.055) ** 2.4
    L = 0.2126 * lin(c.red()) + 0.7152 * lin(c.green()) + 0.0722 * lin(c.blue())
    return QColor(15, 17, 22) if L > 0.36 else QColor(240, 244, 248)        # only the really bright ones


def natural_key(s):
    """S2 before S10, case-insensitive."""
    low = (s or "").strip().lower()
    parts = [(0, int(x), "") if x.isdigit() else (1, 0, x) for x in re.findall(r"\d+|[^\W\d_]+", low)]
    return parts + [(-1, 0, low)]         # shorter name first ([ELMIO] before [ELMIO2]); punctuation only breaks ties


def sort_tags(tags):
    return sorted(tags, key=natural_key)


def ensure_tag_colors(cfg, rng=None):
    """Every tag gets a color; keeps existing ones, drops colors of tags that are gone."""
    import random
    rng = rng or random
    for fc in cfg["fields"].values():
        colors = fc.setdefault("colors", {})
        names = {t.strip().lower() for t in fc.get("tags", [])}
        for k in list(colors):
            if k not in names:
                del colors[k]
        for k in list(colors):
            if colors[k].upper() not in TAG_PALETTE:        # older palettes -> the nearest color of this one
                colors[k] = nearest_palette(colors[k])
        for t in fc.get("tags", []):
            k = t.strip().lower()
            if k not in colors:
                used = {c.upper() for c in colors.values()}
                free = [c for c in TAG_PALETTE if c not in used and c not in TAG_PLAIN]
                colors[k] = rng.choice(free or TAG_PALETTE)
        fc["tags"] = sort_tags(fc.get("tags", []))


def load_config():
    global CONFIG_PATH
    cfg = json.loads(json.dumps(DEFAULT_CONFIG))
    if not CONFIG_PATH.exists() and (APP_DIR / "tagger_config.json").exists() and CONFIG_PATH.parent == APP_DIR:
        CONFIG_PATH = APP_DIR / "tagger_config.json"        # the rename did not work: keep using the old file
    if CONFIG_PATH.exists():
        try:
            saved = json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
            for k, v in saved.items():
                if k == "fields" and isinstance(v, dict):
                    for fk, fv in v.items():          # older configs: only g/c, without enabled/sep
                        if fk in cfg["fields"] and isinstance(fv, dict):
                            cfg["fields"][fk].update(fv)
                    continue
                cfg[k] = v
            cfg["fields"]["g"]["enabled"] = cfg["fields"]["c"]["enabled"] = True
            if saved.get("q_lufs_border") == -11 and saved.get("q_lufs_bad", -14) == -14:   # 1.0.3: new defaults
                cfg["q_lufs_border"], cfg["q_lufs_bad"] = -14, -18
            if saved.get("config_version", 0) < 8:
                # 0.6/0.7 defaulted Genre to "/" which split "Hip-Hop/Rap"; the default is now ","
                if cfg["fields"]["genre"].get("sep") == "/":
                    cfg["fields"]["genre"]["sep"] = ", "
                old = saved.get("smart_dir")
                if old and old not in cfg["smart_dirs"]:
                    cfg["smart_dirs"].append(old)
                cfg["config_version"] = 8
            cfg.pop("smart_dir", None)
            cfg["theme"] = THEME_RENAMED.get(cfg.get("theme", "Neon"), cfg.get("theme", "Neon"))    # 1.2
            for fk in cfg["fields"]:                 # 1.2: the separator only says what is written between tags
                if cfg["fields"][fk].get("sep") not in (", ", "; "):
                    cfg["fields"][fk]["sep"] = ", "
            if isinstance(cfg.get("hotkeys"), dict):           # 0.3-0.7: {"4": {"f", "tag"}}
                cfg["hotkeys"] = [{"key": k, "f": v.get("f", "g"), "tag": v.get("tag", "")}
                                  for k, v in cfg["hotkeys"].items()]
        except Exception:
            log.exception("reading the config failed; using defaults")
    ensure_tag_colors(cfg)
    DEV[0] = bool(cfg.get("developer"))
    return cfg


def save_config(cfg):
    CONFIG_PATH.write_text(json.dumps(cfg, ensure_ascii=False, indent=2), encoding="utf-8")


# --------------------------------------------------------------------------- tag logic
BASE_SPLIT = ",;|"
_SEP_RES = {}


class Vocab(list):
    """A field's tag list plus how the field separates tags: `split` = extra split characters (e.g. "/"),
    `sep` = what to insert when appending to a field that has a single value."""

    def __init__(self, tags=(), split="", sep=", ", space=True, front=None):
        super().__init__(tags)
        self.split, self.sep, self.space = split, sep, space
        self.front = front              # 0.9.23: new tags in front (True) / at the end (False); None = default


def field_split_chars(sep):
    ch = (sep or "").strip()
    return ch if len(ch) == 1 and ch not in BASE_SPLIT else ""


def _sep_re(extra):
    if extra not in _SEP_RES:
        _SEP_RES[extra] = re.compile(r"(\s*[%s]\s*)" % re.escape(BASE_SPLIT + extra))
    return _SEP_RES[extra]
WS_RE = re.compile(r"(\s+)")


def parse(raw, vocab):
    """Split a raw field into tokens and separators. join(tokens, seps) == raw, always.

    1) split on , ; | (+ the field's own separator, e.g. / for Genre)   2) a piece that is a known tag stays whole
    3) Grouping/Comment only (vocab.space): split on spaces when at least one word is a known tag and no word
       looks like source junk (! . : / http, very long words); else keep the piece whole (grey chip).
    """
    if not raw or not raw.strip():
        return [], []
    low = {v.strip().lower() for v in vocab}
    parts = _sep_re(getattr(vocab, "split", "")).split(raw)
    pieces, seps = parts[0::2], parts[1::2]
    if any(not p.strip() for p in pieces):
        return [raw], []
    toks, tseps = [], []
    for i, p in enumerate(pieces):
        core = p.strip()
        words = WS_RE.split(core)
        wtexts, wseps = words[0::2], words[1::2]
        if (getattr(vocab, "space", True) and len(wtexts) > 1 and core.lower() not in low
                and any(w.lower() in low for w in wtexts) and not any(_junk_word(w) for w in wtexts)):
            lead = p[:len(p) - len(p.lstrip())]
            trail = p[len(p.rstrip()):]
            for j, w in enumerate(wtexts):
                text = (lead if j == 0 else "") + w + (trail if j == len(wtexts) - 1 else "")
                toks.append(text)
                if j < len(wseps):
                    tseps.append(wseps[j])
        else:
            toks.append(p)
        if i < len(seps):
            tseps.append(seps[i])
    return toks, tseps


def _junk_word(w):
    lw = w.lower()
    return len(w) > 24 or any(c in w for c in "!.:/\\") or "http" in lw or "www" in lw


def join(toks, seps):
    return "".join(t + (seps[i] if i < len(seps) else "") for i, t in enumerate(toks))


def find_tag(toks, tag):
    t = tag.strip().lower()
    for i, x in enumerate(toks):
        if x.strip().lower() == t:
            return i
    return -1


def remove_at(raw, vocab, i):
    toks, seps = parse(raw, vocab)
    if len(toks) <= 1:
        return ""
    toks, seps = list(toks), list(seps)
    toks.pop(i)
    seps.pop(i if i < len(seps) else i - 1)
    return join(toks, seps)


def append_tag(raw, tag, vocab):
    if not raw or not raw.strip():
        return tag
    toks, seps = parse(raw, vocab)
    if find_tag(toks, tag) >= 0:
        return raw
    default = getattr(vocab, "sep", ", ") or ", "
    if not seps:
        sep = default
    elif " " in tag and not seps[0].strip():
        sep = default if default.strip() else ", "    # a space separator would split "CHRISTMAS 2026"
    else:
        sep = seps[0]
    return raw.rstrip() + sep + tag


TAGS_FRONT = [True]       # 0.9.22: new tags go in front of the field (Settings > General); a list = settable


def prepend_tag(raw, tag, vocab):
    """Put a tag in front of the field (nothing happens if it is already there)."""
    if not raw or not raw.strip():
        return tag
    toks, seps = parse(raw, vocab)
    if find_tag(toks, tag) >= 0:
        return raw
    default = getattr(vocab, "sep", ", ") or ", "
    if not seps:
        sep = default
    elif " " in tag and not seps[0].strip():
        sep = default if default.strip() else ", "
    else:
        sep = seps[0]
    return tag + sep + raw.lstrip()


def add_tag(raw, tag, vocab):
    """A new tag, in front or at the end as set for the field (Tag lists)."""
    front = getattr(vocab, "front", None)
    return (prepend_tag if (TAGS_FRONT[0] if front is None else front) else append_tag)(raw, tag, vocab)


def field_front(cfg, f):
    """0.9.23: do new tags go in front of this field? Grouping / Comment: yes, others (Genre...): at the end,
    unless set otherwise in the Tag lists."""
    fc = cfg["fields"].get(f, {})
    if "front" in fc:
        return bool(fc["front"])
    return f in ("g", "c") and bool(cfg.get("tags_front", True))


def tag_to_front(raw, tag, vocab):
    """0.9.22 "Bring to front": move a tag that is in the field to the first place (else unchanged)."""
    toks, _ = parse(raw, vocab)
    i = find_tag(toks, tag)
    if i <= 0:
        return raw
    real = toks[i].strip()
    return prepend_tag(remove_at(raw, vocab, i), real, vocab)


def toggle_tag(raw, tag, vocab, force=None):
    """force: None=toggle, 'add', 'remove'."""
    toks, _ = parse(raw, vocab)
    i = find_tag(toks, tag)
    if i >= 0 and force != "add":
        return remove_at(raw, vocab, i)
    if i < 0 and force != "remove":
        return add_tag(raw, tag, vocab)
    return raw


def rename_tag(raw, old, new, vocab):
    """Replace tag `old` by `new` in a raw field, keeping the field's separators. If `new` is already there,
    `old` is just removed. `vocab` must still contain `old` so the field is split the same way as before."""
    toks, seps = parse(raw, vocab)
    i = find_tag(toks, old)
    if i < 0:
        return raw
    j = find_tag(toks, new)
    if j >= 0 and j != i:
        return remove_at(raw, vocab, i)
    toks, seps = list(toks), list(seps)
    t = toks[i]
    toks[i] = t[:len(t) - len(t.lstrip())] + new + t[len(t.rstrip()):]
    if " " in new:          # a space separator next to a multi-word tag would split it later
        default = getattr(vocab, "sep", ", ")
        default = default if default.strip() else ", "
        for j in (i - 1, i):
            if 0 <= j < len(seps) and not seps[j].strip():
                seps[j] = default
    return join(toks, seps)


def remove_tag(raw, tag, vocab):
    toks, _ = parse(raw, vocab)
    i = find_tag(toks, tag)
    return raw if i < 0 else remove_at(raw, vocab, i)


JUNK_RE = re.compile(r"https?://|www\.|\.(?:com|net|org|me)\b|converted by|downloaded from|created by|promotional use|"
                     r"free download|^\s*pmedia\b|ripped by|^\s*track\s*\d+\s*$|^\s*flac\s+\d|seed on|"
                     r"t\.me/|^\s*enjoy\b", re.I)          # 0.9.27: more downloader / torrent leftovers


def clean_junk_value(raw, vocab):
    """0.9.9: (cleaned raw, [removed pieces]). Only pieces that look like source junk (links, "Converted by ...")
    go; a piece that is a known tag is never touched, and known tags inside a junk piece are kept."""
    toks, seps = parse(raw, vocab)
    if not toks:
        return raw, []
    low = {v.strip().lower() for v in vocab}
    toks, seps, removed = list(toks), list(seps), []
    for i in range(len(toks) - 1, -1, -1):
        tok = toks[i]
        if tok.strip().lower() in low or not JUNK_RE.search(tok):
            continue
        keep = [w for w in re.split(r"\s+", tok.strip()) if w.lower() in low]
        removed.append(tok.strip())
        if keep:
            toks[i] = " ".join(keep)
            continue
        toks.pop(i)
        if seps:
            seps.pop(i if i < len(seps) else i - 1)
    if not removed:
        return raw, []
    return join(toks, seps).strip(), removed[::-1]


def merge_tags(cur, before, new, vocab):
    """0.9.9 (a): the file holds `cur`, the library showed `before`, the user made it `new`. Apply only what the
    user changed (tags added / removed) to what the file really holds, so nothing in the file is lost."""
    bt = [x.strip() for x in parse(before, vocab)[0]]
    nt = [x.strip() for x in parse(new, vocab)[0]]
    out = cur or ""
    for x in bt:
        if find_tag(nt, x) < 0:
            out = remove_tag(out, x, vocab)
            nx = norm(x).lower()
            for tok in parse(out, vocab)[0]:          # an old copy cut to 28-30 characters
                nt_ = norm(tok).lower()
                if len(nt_) >= 10 and nt_ != nx and nx.startswith(nt_):
                    out = remove_tag(out, tok, vocab)
    for x in nt:
        if find_tag(bt, x) < 0:
            out = append_tag(out, x, vocab)
    # 0.9.22: tags the user put before the old first one (new in front, Bring to front) go first in the file too
    kept = [x for x in bt if find_tag(nt, x) >= 0]
    if kept:
        lead = nt[:find_tag(nt, kept[0])]
        for x in reversed(lead):
            out = tag_to_front(out, x, vocab)
    return out


# ---- keys: always shown in Camelot notation, colored like the Camelot wheel (display only, never written)
_CAMELOT_MINOR = {"G#": 1, "AB": 1, "D#": 2, "EB": 2, "A#": 3, "BB": 3, "F": 4, "C": 5, "G": 6, "D": 7, "A": 8,
                  "E": 9, "B": 10, "F#": 11, "GB": 11, "C#": 12, "DB": 12}
_CAMELOT_MAJOR = {"B": 1, "CB": 1, "F#": 2, "GB": 2, "C#": 3, "DB": 3, "G#": 4, "AB": 4, "D#": 5, "EB": 5,
                  "A#": 6, "BB": 6, "F": 7, "C": 8, "G": 9, "D": 10, "A": 11, "E": 12}
_KEY_RE = re.compile(r"^\s*([A-Ga-g])\s*([#b\u266f\u266d]?)\s*(m|min|minor|maj|major)?\s*$", re.I)


def camelot(key):
    """(number 1-12, 'A' or 'B') for keys like 8A, 08b, Am, A minor, F#m, Bbmaj, Open Key 1m/1d; else None."""
    k = (key or "").strip()
    if not k:
        return None
    m = re.match(r"^0?(\d{1,2})\s*([ABab])$", k)
    if m and 1 <= int(m.group(1)) <= 12:
        return int(m.group(1)), m.group(2).upper()
    m = re.match(r"^(\d{1,2})\s*([mdMD])$", k)          # Open Key: 1d = C major = 8B, 1m = A minor = 8A
    if m and 1 <= int(m.group(1)) <= 12:
        return (int(m.group(1)) + 6) % 12 + 1, "A" if m.group(2).lower() == "m" else "B"
    m = _KEY_RE.match(k.replace("\u266f", "#").replace("\u266d", "b"))
    if not m:
        return None
    note = m.group(1).upper() + ("B" if m.group(2) == "b" else m.group(2).upper())
    q = (m.group(3) or "").lower()
    minor = q in ("m", "min", "minor") and not (q == "m" and m.group(3) == "M")
    table = _CAMELOT_MINOR if minor else _CAMELOT_MAJOR
    n = table.get(note)
    return (n, "A" if minor else "B") if n else None


def camelot_text(key):
    c = camelot(key)
    return "%d%s" % c if c else (key or "")


def camelot_color(c):
    """Pill color for a Camelot key: hue walks round the wheel (1 teal ... 12 light blue); A darker than B."""
    n, ab = c
    hue = ((170 - (n - 1) * 30) % 360) / 360.0
    r, g, b = colorsys.hsv_to_rgb(hue, 0.62, 0.62 if ab == "A" else 0.86)
    return QColor(int(r * 255), int(g * 255), int(b * 255))


def norm(s):
    return (s or "").replace("\r\n", "\n").strip()


def added_date(v):
    """Serato keeps 'date added' as Unix time in seconds (e.g. 1794348075 = 10/11/2026 23:01 in Amsterdam).
    Shown as dd/mm/yyyy in the computer's time zone; anything that is not a number is shown as it is."""
    try:
        return datetime.fromtimestamp(int(str(v).strip())).strftime("%d/%m/%Y")
    except (TypeError, ValueError, OverflowError, OSError):
        return v or ""


