        labels = []                                   # the same label width in the three groups: one column
        for fl in forms.values():
            for r_ in range(fl.rowCount()):
                it = fl.itemAt(r_, QFormLayout.ItemRole.LabelRole)
                if it is not None and isinstance(it.widget(), QLabel):
                    labels.append(it.widget())
        lw = max(QFontMetrics(lb.font()).horizontalAdvance(lb.text()) for lb in labels) + 12
        for lb in labels:
            lb.setFixedWidth(lw)
            lb.setMinimumHeight(28)
        return page

