    # ---- Directories
    def _directories(self):
        page = QWidget()
        v = QVBoxLayout(page)
        v.addWidget(QLabel("<b>Serato library</b> (database V2; the crates are read from the Subcrates folder "
                           "next to it)"))
        row = QHBoxLayout()
        self.lib = QComboBox()
        self.lib.setEditable(True)
