        self.ctl.setHorizontalHeaderLabels(["Action", "Key", ""])
        self.ctl.verticalHeader().setVisible(False)
        self.ctl.horizontalHeader().setSectionResizeMode(0, QHeaderView.ResizeMode.Stretch)
        self.ctl.setColumnWidth(1, 180)
        self.ctl.setColumnWidth(2, 150)
