        info = QLabel("One key can set tags in several fields: + adds a line under it. If the track(s) already "
                      "have all the key's tags, the key removes them; otherwise it adds the missing ones. Pick a tag "
                      "from the list or type a new one.")
        info.setWordWrap(True)
        info.setStyleSheet("color:#9aa3b2;")
        g2v.addWidget(info)
        head = QHBoxLayout()
        head.setContentsMargins(8, 0, 8, 0)          # lines up with the boxes below
        head.setSpacing(6)
        for txt, wdt in (("Key", 114), ("Field", 120), ("Tag", 0)):
            lb = QLabel("<b>%s</b>" % txt)
            if wdt:
                lb.setFixedWidth(wdt)
                head.addWidget(lb)
            else:
                head.addWidget(lb, 1)
        head.addSpacing(64)
        g2v.addLayout(head)
        self.hk_area = QScrollArea()
        self.hk_area.setWidgetResizable(True)
        self.hk_box = QWidget()
        self.hk_lay = QVBoxLayout(self.hk_box)
        self.hk_lay.setContentsMargins(0, 0, 0, 0)
        self.hk_lay.setSpacing(4)
        self.hk_lay.addStretch(1)
        self.hk_area.setWidget(self.hk_box)
        self.hk_area.setMinimumHeight(70)
