            sl.setRange(lo, hi)
            val = QLabel("")
            val.setMinimumWidth(56)
            sl.valueChanged.connect(lambda x, lb=val, sf=suf, scl=sc: lb.setText(
                ("%.1f pt" % (x / scl)) if scl == 10.0 else "%d%s" % (x, sf)))
            self.t_sliders[k] = (sl, sc)
            r, c = i // 2, (i % 2) * 3
            gl.addWidget(QLabel(label), r, c)
            gl.addWidget(sl, r, c + 1)
            gl.addWidget(val, r, c + 2)
