            sl.setRange(0, 100)
            val = QLabel("")
            val.setMinimumWidth(48)
            sl.valueChanged.connect(lambda x, lb=val: lb.setText("%d %%" % x))
            row.addWidget(sl, 1)
            row.addWidget(val)
