        self.t_tint = QPushButton("Tint color")
        self.t_tint.setAutoDefault(False)
        self.t_tint.setMinimumHeight(32)
        self.t_tint.clicked.connect(self._pick_tint)
        fl.addRow("Tint color (vectors / patterns take it; photos become two-color)", self.t_tint)
        self.t_font_ui, self.t_font_title = QFontComboBox(), QFontComboBox()
        fl.addRow("Font (everything)", self.t_font_ui)
        fl.addRow("Font (titles)", self.t_font_title)
        self.t_transport = QComboBox()
        self.t_transport.addItem("Under the title (next to the cover)", "under_title")
        self.t_transport.addItem("Under the cover", "under_cover")
        fl.addRow("Play buttons", self.t_transport)
