class SessionDialog(QDialog):
    """0.9.9 Review and write: what is pending, and what this session wrote, skipped or could not write."""

    def __init__(self, mw):
        super().__init__(mw)
        self.mw = mw
        self.setWindowTitle("Review and write")
        self.resize(1050, 560)
        lay = QVBoxLayout(self)
        self.head = QLabel()
        self.head.setWordWrap(True)
        lay.addWidget(self.head)
        self.tabs = QTabWidget()
        self.tables = {}
        for key in ("pending", "written", "skipped", "failed"):
            tbl = QTableWidget(0, 6)
            tbl.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
            tbl.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows)
            tbl.verticalHeader().setVisible(False)
            hh = tbl.horizontalHeader()
            hh.setSectionResizeMode(QHeaderView.ResizeMode.Interactive)
            hh.setStretchLastSection(True)
            self.tables[key] = tbl
            self.tabs.addTab(tbl, key.capitalize())
        lay.addWidget(self.tabs)
        bb = QDialogButtonBox()
        self.btn_write = bb.addButton("Write all pending now", QDialogButtonBox.ButtonRole.ActionRole)
        self.btn_write.clicked.connect(self._write)
        bb.addButton(QDialogButtonBox.StandardButton.Close)
        bb.rejected.connect(self.reject)
        lay.addWidget(bb)
        self.refresh()
        if not self.tables["pending"].rowCount():
            self.tabs.setCurrentIndex(1)

    def _fill(self, key, headers, rows):
        tbl = self.tables[key]
        tbl.setRowCount(len(rows))
        tbl.setHorizontalHeaderLabels(headers)
        for i, r in enumerate(rows):
            for j, v in enumerate(r):
                v = str(v if v is not None else "")
                it = QTableWidgetItem(v.replace("\n", " ") if v else "")
                it.setToolTip(v)
                tbl.setItem(i, j, it)
        for j, wd in enumerate((70, 230, 80, 190, 190)):
            tbl.setColumnWidth(j, wd)
        n = len(rows)
        self.tabs.setTabText(list(self.tables).index(key), "%s (%d)" % (key.capitalize(), n))

    def refresh(self):
        mw = self.mw
        playing = mw.model.playing
        pend = mw.build_entries()
        failed_before = getattr(mw, "_write_failed", {})
        rows = []
        for e in pend:
            note = []
            if e["row"] == playing:
                note.append("loaded track: written when another track is played, or now (playback pauses briefly)")
            if failed_before.get((e["row"], e["f"])) == e["new"]:
                note.append("could not be written before (see Skipped / Failed)")
            rows.append(("", e["title"], e["fname"], e["before"] or "(empty)", e["new"] or "(empty)", "; ".join(note)))
        self._fill("pending", ["", "Track", "Field", "Library value", "New value", "Note"], rows)
        ses = list(reversed(mw._session))
        self._fill("written", ["Time", "Track", "Field", "The file held", "Written", "Note"],
                   [(r["time"], r["title"], r["fname"], r["file"] or "(empty)", r["after"] or "(empty)", r["why"])
                    for r in ses if r["status"] == "written"])
        for key in ("skipped", "failed"):
            self._fill(key, ["Time", "Track", "Field", "The file holds", "Wanted", "Why"],
                       [(r["time"], r["title"], r["fname"], r["file"] or "(empty)", r["after"] or "(empty)", r["why"])
                        for r in ses if r["status"] == key])
        self.btn_write.setText("Write all pending now (%d)" % len(pend))
        self.btn_write.setEnabled(bool(pend))
        self.head.setText("Pending: %d field change%s. This session: %d written, %d skipped, %d failed.  "
                          "Close Serato before writing, then use Reload ID3 Tags in Serato. Every write is logged "
                          "(Tools > Restore last write)." % (
                              len(pend), "" if len(pend) == 1 else "s",
                              sum(r["status"] == "written" for r in ses), sum(r["status"] == "skipped" for r in ses),
                              sum(r["status"] == "failed" for r in ses)))

    def _write(self):
        n0 = len(self.mw._session)
        self.mw.write_all_now(report=False)
        self.refresh()
        new = self.mw._session[n0:]
        bad = [r for r in new if r["status"] != "written"]
        if bad:
            self.tabs.setCurrentIndex(3 if any(r["status"] == "failed" for r in bad) else 2)
        elif new:
            self.tabs.setCurrentIndex(1)


