def fmt_time(ms):
    s = max(0, int(ms // 1000))
    return "%d:%02d" % (s // 60, s % 60)


# ===================================================================== 0.9.25: Research (year, genre, album,
# producers, remixer, cover) from MusicBrainz, Discogs, iTunes and a SoundCloud link, following the master prompt:
# the exact version first, its own release year (a remix: the remix year), genres from the release's own Discogs
# Genre / Styles (never from the artist), category first, nothing invented. The program proposes, the user decides.
RESEARCH_FIELDS = [("title", "Title"), ("artist", "Artist"), ("year", "Year"), ("genre", "Genre"),
                   ("album", "Album"), ("composer", "Producers"), ("remixer", "Remixer"), ("cover", "Cover")]
_FEAT_RE = re.compile(r"\s*[\(\[]?\s*(?:feat\.?|ft\.?|featuring)\s+([^\)\]]+)[\)\]]?", re.I)


def split_feat(text):
    """'Main feat. A & B' -> ('Main', ['A', 'B'])."""
    m = _FEAT_RE.search(text or "")
    if not m:
        return (text or "").strip(), []
    main = (text[:m.start()] + text[m.end():]).strip(" -")
    names = [x.strip() for x in re.split(r",|&| and ", m.group(1)) if x.strip()]
    return " ".join(main.split()), names
RESEARCH_CACHE = APP_DIR / "research_cache.json"
MB_AGENT = "TagDeck/1.2 (local DJ library tool; https://musicbrainz.org/doc/MusicBrainz_API)"

