class RangeSlider(QWidget):
    """0.9.29: a slider with two handles and its name + range drawn above it. Handles at both ends = not set
    ("–"); a handle at one end leaves that side open. log=True: dense at the small numbers (Plays).
    Double-click the numbers to type a range ("118-126", "-5", "1990-")."""
    changed = Signal()
    PAD = 7

    def __init__(self, name, vmin, vmax, log=False, ticks=None, unit=""):
        super().__init__()
        self.name, self.log, self.ticks, self.unit = name, log, ticks, unit
        self.vmin, self.vmax = float(vmin), float(max(vmax, vmin + 1))
        self.lo, self.hi = self.vmin, self.vmax
        self._drag = None
        self.setMinimumWidth(126)
        f = QFont(self.font())
        f.setPointSizeF(max(6.5, f.pointSizeF() * 0.78))
        self.small = f
        fm = QFontMetrics(f)
        self.setFixedHeight(fm.height() + 20 + (fm.height() if ticks is not None else 0))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setToolTip("%s: drag the two handles; both at the ends = any. Double-click the numbers to type them."
                        % name)

    # value <-> position
    def _f(self, v):
        span = self.vmax - self.vmin
        if self.log:
            return math.log1p(max(0.0, v - self.vmin)) / math.log1p(span)
        return (v - self.vmin) / span

    def _v(self, f):
        f = min(1.0, max(0.0, f))
        if self.log:
            v = self.vmin + math.expm1(f * math.log1p(self.vmax - self.vmin))
        else:
            v = self.vmin + f * (self.vmax - self.vmin)
        return float(min(self.vmax, max(self.vmin, round(v))))

    def _x(self, v):
        return self.PAD + self._f(v) * (self.width() - 2 * self.PAD)

    def _track_y(self):
        return QFontMetrics(self.small).height() + 11

    # API
    def is_set(self):
        return self.lo > self.vmin or self.hi < self.vmax

    def value(self):
        """(low or None, high or None): None = that side open."""
        return (None if self.lo <= self.vmin else self.lo), (None if self.hi >= self.vmax else self.hi)

    def set_value(self, lo=None, hi=None, emit=True):
        lo = self.vmin if lo is None else min(self.vmax, max(self.vmin, float(lo)))
        hi = self.vmax if hi is None else min(self.vmax, max(self.vmin, float(hi)))
        if lo > hi:
            lo, hi = hi, lo
        if (lo, hi) != (self.lo, self.hi):
            self.lo, self.hi = lo, hi
            self.update()
            if emit:
                self.changed.emit()

    def clear(self, emit=True):
        self.set_value(None, None, emit)

    def set_bounds(self, vmin, vmax):
        """New ends (from the library); a set side keeps its value when it is still inside."""
        a, b = self.value()
        self.vmin, self.vmax = float(vmin), float(max(vmax, vmin + 1))
        self.lo = self.vmin if a is None or a <= self.vmin else min(a, self.vmax)
        self.hi = self.vmax if b is None or b >= self.vmax else max(b, self.vmin)
        self.update()

    def _num(self, v):
        return ("%.1f" % v).rstrip("0").rstrip(".") if v != int(v) else str(int(v))

    def text(self):
        a, b = self.value()
        if a is None and b is None:
            return "–"
        if b is None:
            return "≥ " + self._num(a)
        if a is None:
            return "≤ " + self._num(b)
        return "%s – %s" % (self._num(a), self._num(b))

    # drawing
    def paintEvent(self, ev):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        dim = QColor(THEME.get("text_dim", "#8a94a8"))
        tx = QColor(THEME.get("text", "#e6edf7")) if not THEME.get("classic") else self.palette().text().color()
        acc = QColor(THEME.get("accent", "#3daee9"))
        p.setFont(self.small)
        fm = QFontMetrics(self.small)
        on = self.is_set()
        p.setPen(dim)
        p.drawText(QRect(0, 0, self.width(), fm.height()), Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter,
                   self.name.upper())
        p.setPen(tx if on else dim)
        p.drawText(QRect(0, 0, self.width(), fm.height()), Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter,
                   self.text())
        y = self._track_y()
        x0, x1 = self.PAD, self.width() - self.PAD
        p.setPen(Qt.PenStyle.NoPen)
        groove = QColor(dim)
        groove.setAlpha(70)
        p.setBrush(groove)
        p.drawRoundedRect(QRectF(x0, y - 1.5, x1 - x0, 3), 1.5, 1.5)
        a, b = self._x(self.lo), self._x(self.hi)
        if on:
            p.setBrush(acc)
            p.drawRect(QRectF(a, y - 1.5, b - a, 3))
        knob = tx if on else dim
        for x in (a, b):
            p.setBrush(knob)
            p.drawEllipse(QPointF(x, y), 6, 6)
        if self.ticks is not None:
            p.setPen(dim)
            ty = y + 9
            ticks = list(self.ticks) or [self.vmin, self.vmax]
            last = -1e9
            for i, t in enumerate(ticks):
                if not (self.vmin <= t <= self.vmax):
                    continue
                s = self._num(t)
                w = fm.horizontalAdvance(s)
                cx = self._x(t)
                left = 0 if i == 0 else (self.width() - w if i == len(ticks) - 1 else cx - w / 2)
                left = max(0, min(self.width() - w, left))
                if left < last + 4:
                    continue
                p.drawText(QRectF(left, ty, w + 1, fm.height()), Qt.AlignmentFlag.AlignLeft, s)
                last = left + w
        p.end()

    # mouse
    def mousePressEvent(self, ev):
        if ev.button() != Qt.MouseButton.LeftButton:
            return super().mousePressEvent(ev)
        x = ev.position().x()
        a, b = self._x(self.lo), self._x(self.hi)
        if abs(a - b) < 2:
            self._drag = "lo" if x < a else "hi"
        else:
            self._drag = "lo" if abs(x - a) <= abs(x - b) else "hi"
        self._move(x)

    def mouseMoveEvent(self, ev):
        if self._drag:
            self._move(ev.position().x())

    def mouseReleaseEvent(self, ev):
        self._drag = None

    def _move(self, x):
        v = self._v((x - self.PAD) / max(1.0, self.width() - 2 * self.PAD))
        if self._drag == "lo":
            self.set_value(min(v, self.hi), None if self.hi >= self.vmax else self.hi)
        else:
            self.set_value(None if self.lo <= self.vmin else self.lo, max(v, self.lo))

    def mouseDoubleClickEvent(self, ev):
        from PySide6.QtWidgets import QInputDialog
        a, b = self.value()
        cur = "" if a is None and b is None else "%s-%s" % ("" if a is None else self._num(a),
                                                            "" if b is None else self._num(b))
        txt, ok = QInputDialog.getText(self, self.name, "%s from - to (e.g. 118-126, 1990-, -5; empty = any):"
                                       % self.name, text=cur)
        if ok:
            self.set_text(txt)

    def set_text(self, txt):
        """'118-126', '118-', '-126', '120' (= 120-120), '' (= any)."""
        txt = (txt or "").strip().replace("–", "-").replace(",", ".")
        if not txt:
            return self.clear()
        m = re.match(r"^\s*(\d+(?:\.\d+)?)?\s*(-)?\s*(\d+(?:\.\d+)?)?\s*$", txt)
        if not m or not (m.group(1) or m.group(3)):
            return
        lo = float(m.group(1)) if m.group(1) else None
        hi = float(m.group(3)) if m.group(3) else (None if m.group(2) else lo)
        self.set_value(lo, hi)


class FilterTagEdit(ChipEdit):
    """0.9.29: one field for a tag filter. Chips = tags a track must have; click a chip to turn it into "must
    NOT have" (red, crossed out), x removes it, + adds from the tag list; ALL / ANY at the right. A double-click
    edits it as text: "peak time, vocal, -acapella"."""
    AUTO_FIT = False

    def __init__(self, mw, f):
        super().__init__(mw, f)
        self.items = []                         # [(tag, excluded)]
        self.mode = "all"
        ch = ChipDelegate.line_height(self.font())
        self.setMinimumHeight(ch + 8)
        self.setFixedHeight(ch + 8)
        self.setMinimumWidth(230)
        self.setToolTip("Tags a track must have. Click a tag: must NOT have (red). x removes, + adds.\n"
                        "ALL / ANY: the track needs all of the tags, or one of them. Double-click: edit as text "
                        "(-tag = must not have).")

    # text <-> items
    def currentText(self):
        return ", ".join(("-" if ex else "") + t for t, ex in self.items)

    def setEditText(self, text):
        items = []
        for piece in re.split(r"[,;|]", text or ""):
            t = piece.strip()
            ex = t.startswith("-")
            t = t.lstrip("-").strip()
            if t and t.lower() not in [x.lower() for x, _ in items]:
                items.append((t, ex))
        self.items = items
        self.update()

    def inc(self):
        return [t for t, ex in self.items if not ex]

    def exc(self):
        return [t for t, ex in self.items if ex]

    def clear(self):
        self.items, self.mode = [], "all"
        self.update()

    def _mode_rect(self):
        fm = QFontMetrics(self._mode_font())
        w = fm.horizontalAdvance("ANY") + 12
        r = self.rect()
        return QRect(r.right() - w - 4, r.top() + 4, w, r.height() - 8)

    def _mode_font(self):
        f = QFont(self.font())
        f.setPointSizeF(max(6.5, f.pointSizeF() * 0.75))
        f.setBold(True)
        return f

    def _rect(self):
        return self.rect().adjusted(2, 2, -(self._mode_rect().width() + 8), -2)

    def _toks(self):
        known = {x.lower() for x in self.mw.cfg["fields"][self.f]["tags"]}
        return [(t, t.lower() in known or True) for t, _ in self.items]

    def paintEvent(self, ev):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setPen(QPen(QColor(128, 128, 128, 110) if THEME.get("classic") else QColor(255, 255, 255, 30), 1))
        p.setBrush(Qt.BrushStyle.NoBrush if THEME.get("classic") else QColor(0, 0, 0, 70))
        p.drawRoundedRect(QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5), 5, 5)
        if not self.edit.isVisible():
            chips, plus, truncated, _, cfont = self.d.layout(self._rect(), self._toks(), self.font())
            p.setFont(cfont)
            colors = self.mw.cfg.get("fields", {}).get(self.f, {}).get("colors", {})
            for r, label, _known, i, xr in chips:
                tag, ex = self.items[i]
                if ex:
                    red = QColor("#e05252")
                    p.setPen(QPen(red, 1))
                    p.setBrush(Qt.BrushStyle.NoBrush)
                    p.drawRoundedRect(QRectF(r).adjusted(0.5, 0.5, -0.5, -0.5), 4, 4)
                    fg = QColor("#f08a8a")
                else:
                    p.setPen(Qt.PenStyle.NoPen)
                    hexc = colors.get(tag.strip().lower())
                    base = QColor(hexc) if hexc else ChipDelegate.COLORS.get(self.f, QColor(71, 85, 105))
                    p.setBrush(base)
                    p.drawRoundedRect(r, 4, 4)
                    fg = chip_text_color(base)
                p.setPen(fg)
                tr = QRect(r.left() + 7, r.top(), r.width() - 7 - xr.width(), r.height())
                p.drawText(tr, Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft, label)
                if ex:
                    w = min(tr.width(), QFontMetrics(cfont).horizontalAdvance(label))
                    p.drawLine(QPointF(tr.left(), r.center().y() + 0.5), QPointF(tr.left() + w, r.center().y() + 0.5))
                p.drawText(xr, Qt.AlignmentFlag.AlignCenter, "×")
            dim = QColor(THEME.get("text_dim", "#8a94a8"))
            if not self.items:
                p.setPen(dim)
                hr = self._rect().adjusted(plus.width() + 10, 0, 0, 0)
                p.drawText(hr, Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft,
                           QFontMetrics(cfont).elidedText("add a tag, or -tag to exclude", Qt.TextElideMode.ElideRight,
                                                          max(10, hr.width() - 4)))
            p.setPen(QPen(dim, 1))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawRoundedRect(QRectF(plus).adjusted(1.5, 1.5, -1.5, -1.5), 4, 4)
            p.drawText(plus, Qt.AlignmentFlag.AlignCenter, "+")
        mr = self._mode_rect()
        p.setFont(self._mode_font())
        p.setPen(QPen(QColor(THEME.get("text_dim", "#8a94a8")), 1))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRoundedRect(QRectF(mr).adjusted(0.5, 0.5, -0.5, -0.5), 4, 4)
        p.setPen(QColor(THEME.get("text", "#e6edf7")) if not THEME.get("classic") else self.palette().text().color())
        p.drawText(mr, Qt.AlignmentFlag.AlignCenter, self.mode.upper())
        p.end()

    def mousePressEvent(self, ev):
        if ev.button() != Qt.MouseButton.LeftButton or self.edit.isVisible():
            return QWidget.mousePressEvent(self, ev)
        pos = ev.position().toPoint()
        if self._mode_rect().contains(pos):
            self.mode = "any" if self.mode == "all" else "all"
            self.update()
            self.changed.emit()
            return
        chips, plus, _, _, _ = self.d.layout(self._rect(), self._toks(), self.font())
        for r, _, _, i, xr in chips:
            if xr.contains(pos):
                del self.items[i]
                self.update()
                self.changed.emit()
                return
            if r.contains(pos):
                t, ex = self.items[i]
                self.items[i] = (t, not ex)
                self.update()
                self.changed.emit()
                return
        if plus.contains(pos) or not self.items:
            m = QMenu(self)
            have = {t.lower(): ex for t, ex in self.items}
            for tag in sort_tags(self.mw.cfg["fields"][self.f]["tags"]):
                mark = ("✕ " if have[tag.lower()] else "✓ ") if tag.lower() in have else "    "
                a = m.addAction(mark + tag)
                a.triggered.connect(lambda _=False, t=tag: self._toggle(t))
            if not self.mw.cfg["fields"][self.f]["tags"]:
                m.addAction("(the %s tag list is empty: Tools > Tag lists)" % self.mw.cfg["fields"][self.f]["name"]
                            ).setEnabled(False)
            m.exec(self.mapToGlobal(plus.bottomLeft()))

    def _toggle(self, tag):
        low = [t.lower() for t, _ in self.items]
        if tag.lower() in low:
            del self.items[low.index(tag.lower())]
        else:
            self.items.append((tag, False))
        self.update()
        self.changed.emit()

    def mouseDoubleClickEvent(self, ev):
        if self._mode_rect().contains(ev.position().toPoint()):
            return
        self.edit.setGeometry(self._rect())
        self.edit.setText(self.currentText())
        self.edit.show()
        self.edit.setFocus()
        self.edit.selectAll()
        self.update()

    def _edited(self):
        if not self.edit.isVisible():
            return
        self.edit.hide()
        old = self.currentText()
        self.setEditText(self.edit.text())
        if self.currentText() != old:
            self.changed.emit()
        self.update()


def color_swatch_icon(values, w=34, h=20):
    """0.9.29: the Color filter button: a square with "–" (none chosen) or the chosen colours side by side."""
    dpr = 2
    pm = QPixmap(w * dpr, h * dpr)
    pm.setDevicePixelRatio(dpr)
    pm.fill(QColor(0, 0, 0, 0))
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    dim = QColor(THEME.get("text_dim", "#8a94a8"))
    cols = [qc for qc, val, _ in track_color_choices() if val in values and qc is not None]
    if not cols:
        p.setPen(QPen(dim, 1))
        p.setBrush(Qt.BrushStyle.NoBrush)
        side = h - 2
        r = QRectF((w - side) / 2, 1, side, side)
        p.drawRoundedRect(r, 3, 3)
        p.drawLine(QPointF(r.left() + side * 0.3, r.center().y()), QPointF(r.right() - side * 0.3, r.center().y()))
    else:
        cols = cols[:4]
        n = len(cols)
        gap = 2
        cw = (w - gap * (n - 1)) / n
        for i, qc in enumerate(cols):
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(qc)
            p.drawRoundedRect(QRectF(i * (cw + gap), 1, cw, h - 2), 2, 2)
    p.end()
    return QIcon(pm)


class FilterBar(QWidget):
    """0.9.27: filters over what is shown (crate / folder / search). 0.9.29: one row of small boxes - BPM, Year
    and Plays as sliders with two handles (Plays dense at the small numbers), x2 for half / double BPM, Color as
    a swatch, Quality, one field each for Grouping and Comment (click a tag = must not have; ALL / ANY), then
    Save as crate (asks: smart or normal) and Clear. Starts empty every time."""
    changed = Signal()

    def __init__(self, mw):
        super().__init__()
        self.mw = mw
        self.setObjectName("filterBar")
        edge = _filter_edge()
        if not THEME.get("classic"):
            self.setStyleSheet("#fBox{border:1px solid %s;border-radius:8px;background:rgba(0,0,0,40);}"
                               "#fBox QLabel{background:transparent;}"
                               "#fBox QToolButton, #fBox QPushButton, #fBox QComboBox{border:1px solid %s;}"
                               "#fBox QToolButton:checked{border:1px solid %s;background:%s;color:%s;}"
                               "#fBox QToolButton::menu-indicator{image:none;width:0;}"
                               % (edge, edge, THEME.get("accent", "#3daee9"), _rgba(THEME.get("accent", "#3daee9"), 0.16),
                                  THEME.get("accent", "#3daee9")))
        v = QVBoxLayout(self)
        v.setContentsMargins(0, 0, 0, 4)
        v.setSpacing(6)
        self.r1, self.r2 = QHBoxLayout(), QHBoxLayout()
        for r in (self.r1, self.r2):
            r.setSpacing(8)
            r.setContentsMargins(0, 0, 0, 0)
        v.addLayout(self.r1)
        v.addLayout(self.r2)

        def box(title, *widgets, stretch=False):
            w = QWidget()
            w.setObjectName("fBox")
            w.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
            bl = QVBoxLayout(w)
            bl.setContentsMargins(9, 5, 9, 6)
            bl.setSpacing(3)
            if title:
                lb = QLabel(title.upper())
                f = QFont(lb.font())
                f.setPointSizeF(max(6.5, f.pointSizeF() * 0.78))
                lb.setFont(f)
                lb.setStyleSheet("color:%s;" % THEME.get("text_dim", "#8a94a8"))
                bl.addWidget(lb)
            row = QHBoxLayout()
            row.setContentsMargins(0, 0, 0, 0)
            row.setSpacing(6)
            for x in widgets:
                row.addWidget(x, 1 if stretch else 0)
            bl.addLayout(row)
            return w

        self.bpm = RangeSlider("BPM", 50, 220)
        self.half = QToolButton()
        self.half.setText("×2")
        self.half.setCheckable(True)
        self.half.setToolTip("Also tracks at half or double this BPM (e.g. 85-95 also finds 170-190)")
        self.half.toggled.connect(lambda _: self.changed.emit())
        self.year = RangeSlider("Year", 1960, datetime.now().year, ticks=[])
        self.plays = RangeSlider("Plays", 0, 100, log=True, ticks=[0, 5, 20, 100])
        for rs in (self.bpm, self.year, self.plays):
            rs.changed.connect(self.changed.emit)
        self.colors = set()
        self.color_btn = QToolButton()
        self.color_btn.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
        self.color_btn.setIconSize(QSize(34, 20))
        self.color_btn.setToolTip("Track color: pick one or more")
        cm = QMenu(self.color_btn)
        for qc, val, name in track_color_choices():
            a = cm.addAction(name)
            a.setCheckable(True)
            if qc is not None:
                pm = QPixmap(14, 14)
                pm.fill(qc)
                a.setIcon(QIcon(pm))
            a.toggled.connect(lambda on, vv=val: self._color(vv, on))
        self.color_menu = cm
        self.color_btn.setMenu(cm)
        self.color_clear = QToolButton()
        self.color_clear.setText("×")
        self.color_clear.setToolTip("Any color")
        self.color_clear.clicked.connect(self._color_none)
        self.color_clear.setVisible(False)
        self.quality = QComboBox()
        for key, label in (("", "–"), ("good", "Good"), ("dynamic", "Dynamic master"), ("border", "Borderline"),
                           ("bad", "Bad"), ("notbad", "Not bad"), ("none", "Not checked")):
            self.quality.addItem(label, key)
        self.quality.setToolTip("Quality is measured when a track plays, or with right-click > Check quality")
        self.quality.currentIndexChanged.connect(lambda _: self.changed.emit())
        self.q_check = QPushButton("")                  # 0.9.30: "23 not checked · Check"
        self.q_check.setFlat(True)
        self.q_check.setAutoDefault(False)
        self.q_check.setCursor(Qt.CursorShape.PointingHandCursor)
        self.q_check.setStyleSheet("QPushButton{border:none;background:transparent;padding:0 2px;color:%s;"
                                   "text-decoration:underline;}" % THEME.get("accent", "#3daee9"))
        self.q_check.setToolTip("These tracks are hidden by the Quality filter because they were not measured yet.\n"
                                "Click: measure them now (in the background); the list follows as results come.")
        self.q_check.clicked.connect(self._check_unchecked)
        self.q_check.setVisible(False)
        self._unchecked = []
        self.tagw = {}
        for f in ("g", "c"):
            e = FilterTagEdit(mw, f)
            e.changed.connect(self.changed.emit)
            self.tagw[f] = e
        self.b_save = QPushButton("Save as crate...")
        self.b_save.setAutoDefault(False)
        self.b_save.setToolTip("Save what the filters show as a crate: a smart crate (updates itself) or a "
                               "normal one (these tracks)")
        self.b_save.clicked.connect(self._save_smart)
        bc = QPushButton("Clear")
        bc.setAutoDefault(False)
        bc.clicked.connect(self.clear)
        self.b_clear = bc
        btns = QWidget()
        bv = QVBoxLayout(btns)
        bv.setContentsMargins(0, 0, 0, 0)
        bv.setSpacing(4)
        bv.addWidget(self.b_save)
        bv.addWidget(bc)
        self._left = [box(None, self.bpm, self.half, stretch=False), box(None, self.year), box(None, self.plays),
                      box("Color", self.color_btn, self.color_clear), box("Quality", self.quality, self.q_check)]
        self._left[0].layout().itemAt(0).layout().setStretch(0, 1)
        self.bpm.setMinimumWidth(136)
        self._tags = [box(mw.cfg["fields"]["g"]["name"], self.tagw["g"], stretch=True),
                      box(mw.cfg["fields"]["c"]["name"], self.tagw["c"], stretch=True)]
        self._btns = btns
        self._two = None
        self._arrange(False)
        self._color_show()

    def _arrange(self, two):
        if two == self._two:
            return
        self._two = two
        for r in (self.r1, self.r2):
            while r.count():
                r.takeAt(0)
        for w in self._left:
            self.r1.addWidget(w)
        if two:
            self.r1.addStretch(1)
            self.r1.addWidget(self._btns)
            for w in self._tags:
                self.r2.addWidget(w, 1)
        else:
            for w in self._tags:
                self.r1.addWidget(w, 1)
            self.r1.addWidget(self._btns)

    def _one_row_width(self):
        return (sum(w.minimumSizeHint().width() for w in self._left + self._tags) + self._btns.sizeHint().width()
                + 8 * (len(self._left) + len(self._tags)))

    def resizeEvent(self, ev):
        super().resizeEvent(ev)
        self._arrange(self.width() < self._one_row_width())

    def minimumSizeHint(self):
        """As narrow as the two-row arrangement, so the window can still be made narrower."""
        w = sum(x.minimumSizeHint().width() for x in self._left) + self._btns.sizeHint().width() + 8 * len(self._left)
        return QSize(w, super().minimumSizeHint().height())

    def showEvent(self, ev):
        super().showEvent(ev)
        self.update_bounds()
        self._arrange(self.width() < self._one_row_width())

    def update_bounds(self):
        """Year from the oldest year in the library to this year; Plays up to the most played; BPM 50-220 or the
        library's range inside that."""
        tracks = getattr(self.mw.model, "tracks", []) or []
        years = [y for y in (_year(t.get("year")) for t in tracks) if y]
        self.year.set_bounds(min(years) if years else 1960, datetime.now().year)
        self.year.ticks = []
        plays = []
        for t in tracks:
            try:
                plays.append(int(t.get("playcount") or 0))
            except ValueError:
                pass
        mx = max([10] + plays)
        self.plays.set_bounds(0, mx)
        self.plays.ticks = [x for x in (0, 5, 20, 100, 500) if x < mx * 0.8] + [mx]
        bpms = []
        for t in tracks:
            try:
                b = float(t.get("bpm") or 0)
            except ValueError:
                continue
            if 40 <= b <= 250:
                bpms.append(b)
        if bpms:
            self.bpm.set_bounds(max(50, math.floor(min(bpms))), min(220, math.ceil(max(bpms))))

    def _color(self, val, on):
        (self.colors.add if on else self.colors.discard)(val)
        self._color_show()
        self.changed.emit()

    def _color_none(self):
        for a in self.color_menu.actions():
            a.blockSignals(True)
            a.setChecked(False)
            a.blockSignals(False)
        self.colors.clear()
        self._color_show()
        self.changed.emit()

    def _color_show(self):
        self.color_btn.setIcon(color_swatch_icon(self.colors))
        self.color_clear.setVisible(bool(self.colors))
        names = [name for qc, val, name in track_color_choices() if val in self.colors]
        self.color_btn.setToolTip("Track color: %s" % (", ".join(names) if names else "any (pick one or more)"))

    def clear(self):
        self.blockSignals(True)
        for rs in (self.bpm, self.year, self.plays):
            rs.clear(emit=False)
            rs.update()
        self.half.setChecked(False)
        for a in self.color_menu.actions():
            a.setChecked(False)
        self.colors.clear()
        self._color_show()
        self.quality.setCurrentIndex(0)
        for e in self.tagw.values():
            e.clear()
        self.blockSignals(False)
        self.changed.emit()

    def count(self):
        n = sum(1 for rs in (self.bpm, self.year, self.plays) if rs.is_set())
        n += bool(self.colors) + bool(self.quality.currentData())
        n += sum(1 for e in self.tagw.values() for x in (e.inc(), e.exc()) if x)
        return n

    def _check_unchecked(self):
        rows = list(self._unchecked)
        if rows:
            self.mw.check_quality(rows)
            self.mw.statusBar().showMessage("Checking quality of %d tracks..." % len(rows), 4000)

    def set_unchecked(self, rows):
        """0.9.30: the tracks a Quality filter hides only because they were never measured."""
        self._unchecked = rows
        n = len(rows)
        self.q_check.setText("%d not checked \u00B7 Check" % n if n else "")
        self.q_check.setVisible(bool(n))

    def predicate(self, skip_quality=False):
        """A function track-dict -> bool for what is set (None when nothing is set)."""
        if not self.count():
            return None
        mw = self.mw
        bl, bh = self.bpm.value()
        yl, yh = self.year.value()
        pl, ph = self.plays.value()
        half = self.half.isChecked()
        colors = set(self.colors)
        qual = None if skip_quality else self.quality.currentData()
        tags = {}
        for f, e in self.tagw.items():
            if e.inc() or e.exc():
                tags[f] = (e.mode, e.inc(), e.exc(), mw.model.vocab(f))

        def inr(x, lo, hi):
            return (lo is None or x >= lo) and (hi is None or x <= hi)

        def ok(t):
            if bl is not None or bh is not None:
                try:
                    b = float(t.get("bpm") or 0)
                except ValueError:
                    return False
                if not b or not (inr(b, bl, bh) or (half and (inr(b * 2, bl, bh) or inr(b / 2, bl, bh)))):
                    return False
            if yl is not None or yh is not None:
                y = _year(t.get("year"))
                if y is None or not inr(y, yl, yh):
                    return False
            if pl is not None or ph is not None:
                try:
                    p = int(t.get("playcount") or 0)
                except ValueError:
                    p = 0
                if not inr(p, pl, ph):
                    return False
            if colors and color_value(t) not in colors:
                return False
            if qual:
                q = mw.quality.get(t["full"]) if hasattr(mw, "quality") else None
                v = quality_verdict(q, mw.cfg, t.get("year"))[0] if q else None
                if qual == "none":
                    if v is not None:
                        return False
                elif qual == "notbad":
                    if v in (None, "bad"):
                        return False
                elif v != qual:
                    return False
            for f, (mode, ii, ee, voc) in tags.items():
                toks = parse(t.get(f) or "", voc)[0]
                if ii:
                    hits = [find_tag(toks, x) >= 0 for x in ii]
                    if not (all(hits) if mode == "all" else any(hits)):
                        return False
                if any(find_tag(toks, x) >= 0 for x in ee):
                    return False
            return True
        return ok

    def smart_rules(self):
        """-> (rules, match_all, what a Serato smart crate cannot do)."""
        rules, lost, any_groups = [], [], []
        bl, bh = self.bpm.value()
        if bl is not None:
            rules.append({"field": 15, "cmp": "cond_greq_uint", "value": str(int(math.floor(bl)))})
        if bh is not None:
            rules.append({"field": 15, "cmp": "cond_lseq_uint", "value": str(int(math.ceil(bh)))})
        if self.half.isChecked() and (bl is not None or bh is not None):
            lost.append("BPM ×2 (half / double)")
        yl, yh = self.year.value()
        if yl is not None:
            rules.append({"field": 23, "cmp": "cond_aft_str", "value": str(int(yl) - 1)})
        if yh is not None:
            rules.append({"field": 23, "cmp": "cond_bef_str", "value": str(int(yh) + 1)})
        pl, ph = self.plays.value()
        if pl is not None:
            rules.append({"field": 79, "cmp": "cond_greq_uint", "value": str(max(0, int(pl)))})
        if ph is not None:
            rules.append({"field": 79, "cmp": "cond_lseq_uint", "value": str(max(0, int(ph)))})
        for f, fid in (("g", 19), ("c", 17)):
            e = self.tagw[f]
            ii, ee = e.inc(), e.exc()
            if e.mode == "any" and len(ii) > 1:
                any_groups.append(f)
            rules += [{"field": fid, "cmp": "cond_con_str", "value": x} for x in ii]
            rules += [{"field": fid, "cmp": "cond_dnc_str", "value": x} for x in ee]
        if self.colors:
            lost.append("Color")
        if self.quality.currentData():
            lost.append("Quality")
        match_all = True
        if any_groups:
            fid = {"g": 19, "c": 17}[any_groups[0]]
            only_any = len(any_groups) == 1 and all(r["cmp"] == "cond_con_str" and r["field"] == fid for r in rules)
            if only_any:
                match_all = False
            else:
                lost.append("%s ANY together with other filters" %
                            " / ".join(self.mw.cfg["fields"][f]["name"] for f in any_groups))
        return rules, match_all, lost

    def shown_rows(self):
        px = self.mw.proxy
        return [px.mapToSource(px.index(i, 0)).row() for i in range(px.rowCount())]

    def _save_smart(self):
        """0.9.29: asks first: a smart crate (updates itself) or a normal crate (the tracks shown now). When the
        filters cannot be a Serato smart crate, says why and offers the normal one."""
        mw = self.mw
        if hasattr(mw, "_filter_timer") and mw._filter_timer.isActive():
            mw._filter_timer.stop()
            mw._apply_filters()
        rules, match_all, lost = self.smart_rules()
        rows = self.shown_rows()
        box = QMessageBox(self)
        box.setWindowTitle("Save as crate")
        box.setIcon(QMessageBox.Icon.Question)
        text = ("Save what the filters show as a crate.\n\n"
                "Smart crate: Serato keeps it up to date as your tracks change.\n"
                "Normal crate: the %d track%s shown now; it does not change by itself."
                % (len(rows), "" if len(rows) == 1 else "s"))
        if lost or not rules:
            text += ("\n\nA smart crate is not possible with these filters: Serato smart crates cannot do %s."
                     % ", ".join(lost or ["what is set"]))
        box.setText(text)
        b_smart = box.addButton("Smart crate", QMessageBox.ButtonRole.AcceptRole)
        b_norm = box.addButton("Normal crate", QMessageBox.ButtonRole.AcceptRole)
        box.addButton(QMessageBox.StandardButton.Cancel)
        b_smart.setEnabled(bool(rules) and not lost)
        b_norm.setEnabled(bool(rows))
        box.setDefaultButton(b_smart if b_smart.isEnabled() else b_norm)
        box.exec()
        clicked = box.clickedButton()
        if clicked is b_smart:
            mw.smart_new([], sc={"match_all": match_all, "live": True, "rules": rules}, name="Filtered")
        elif clicked is b_norm:
            mw.crate_new([], rows, default="Filtered")


class MainWindow(TitleBarMixin, QMainWindow):
    def __init__(self, cfg):
        super().__init__()
        self.cfg = cfg
        self.setWindowTitle("%s \u2014 %s" % (APP_NAME, APP_SLOGAN))
        self.setWindowIcon(app_icon())
        self.resize(1400, 820)
        SCROLL_MARGIN[0] = int(cfg.get("scroll_margin", 3))
        self._stall = StallWatch(self)             # 0.9.22: slow moments go to the log
        self.quality = QualityStore()              # 0.9.27
        self._qsig = _QualitySignal()
        self._qsig.done.connect(self._quality_done)
        self._q_queue, self._q_lock, self._q_running = [], threading.Lock(), False
        QTimer.singleShot(1500, lambda: threading.Thread(target=fallback_decoders, daemon=True).start())
        self.model = TrackModel(cfg)
        self.proxy = TrackProxy()
        self.proxy.setSourceModel(self.model)
        self.shortcuts = []
        self.player = None
        self.rel_index = {}
        self.crate_cache = {}
        self.smart_cache = {}
        self._live_smart = False
        self.smart_timer = QTimer(self)
        self.smart_timer.setSingleShot(True)
        self.smart_timer.setInterval(150)
        self.smart_timer.timeout.connect(self._refresh_smart)
        self._twin_timer = QTimer(self)                 # 1.1: twin crates follow their smart crates
        self._twin_timer.setSingleShot(True)
        self._twin_timer.setInterval(1500)
        self._twin_timer.timeout.connect(self.twin_sync)
        self._twin_poll = QTimer(self)                  # ... and wait while Serato runs
        self._twin_poll.setInterval(10000)
        self._twin_poll.timeout.connect(self._twin_poll_tick)
        self._twin_waiting = []
        self.db_path = ""
        self.wf = WaveformLoader()
        self.wf.ready.connect(self._on_wave_ready)
        self.wf.progress.connect(self._on_wave_progress)
        self.wf.failed.connect(self._on_wave_failed)
        self.wf.decoder.connect(self._on_wave_decoder)
        self.wf.set_mode(cfg.get("wf_decoder", "auto"))
        self._build_ui()
        self._build_audio()
        self._build_menus()
        self._install_titlebar()                  # 0.9.29
        if getattr(self, "_tb", None) is not None:     # 1.2: Undo / Redo / status right of Help
            self._tb.set_lead(self.top_actions)
        else:
            self.menuBar().setCornerWidget(self.top_actions, Qt.Corner.TopRightCorner)
        self._layout_timer = QTimer(self)          # 1.1.3: window, crate panel and columns are saved soon after a
        self._layout_timer.setSingleShot(True)     # change (not only when TagDeck closes)
        self._layout_timer.setInterval(1500)
        self._layout_timer.timeout.connect(self._save_layout)
        self._restore_window()
        hh_ = self.view.horizontalHeader()
        hh_.sectionResized.connect(self._layout_changed)
        hh_.sectionMoved.connect(self._layout_changed)
        self.main_split.splitterMoved.connect(self._layout_changed)
        self._rebuild_hotkeys()
        self.autowrite = QTimer(self)
        self.autowrite.setSingleShot(True)
        self.autowrite.setInterval(3000)
        self.autowrite.timeout.connect(self._auto_write)
        self._write_failed, self._problems, self._writing = {}, [], False
        self._session = []                # 0.9.9: every write attempt of this session (Review and write shows it)
        self.model.changed.connect(self._update_status)
        self.model.changed.connect(self.smart_timer.start)
        self.model.changed.connect(self._twin_timer.start)
        self.model.changed.connect(self._schedule_auto_write)
        self.model.stackChanged.connect(self._update_undo)
        self.model.file_handler = self.file_op
        self.model.rename_handler = self.rename_one
        self.model.quality_of = self._quality_of
        self.model.status_of = self._status_of                         # 1.2
        self._keep_focus_on_list()
        self.apply_texts()
        self._update_undo()
        if cfg.get("library") and Path(cfg["library"]).exists():
            self.load_library(cfg["library"])
        else:
            self._update_status()

    # ---- keyboard focus (0.9.11): the track list keeps it; buttons, sliders and combos never take it
    def _keep_focus_on_list(self):
        from PySide6.QtWidgets import QAbstractButton, QAbstractSlider
        for w in self.findChildren(QAbstractButton) + self.findChildren(QAbstractSlider) + \
                self.findChildren(QComboBox):
            w.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        QApplication.instance().focusChanged.connect(self._focus_guard)

    def _focus_guard(self, old, new):
        if new is None or new.window() is not self or not self.isVisible():
            return
        if new is self.view or self.view.isAncestorOf(new) or new is self.tree or isinstance(new, QLineEdit):
            return
        QTimer.singleShot(0, self._focus_list)

    def _focus_list(self):
        fw = QApplication.focusWidget()
        if fw is not None and (fw is self.tree or isinstance(fw, QLineEdit) or self.view.isAncestorOf(fw)):
            return
        self.view.setFocus(Qt.FocusReason.OtherFocusReason)

    def eventFilter(self, obj, ev):
        if self._tb_event(obj, ev):
            return True
        return super().eventFilter(obj, ev)

    def showEvent(self, ev):
        super().showEvent(ev)
        self._tb_show()
        self._tb_layout()

    # ---- 1.1.3: window size / place / maximized, crate panel width and columns are remembered
    def _restore_window(self):
        g = self.cfg.get("window")
        self._start_max = False
        if not isinstance(g, dict):
            return
        try:
            from PySide6.QtCore import QRect as _R
            r = _R(int(g["x"]), int(g["y"]), max(500, int(g["w"])), max(400, int(g["h"])))
            screens = [sc.availableGeometry() for sc in QApplication.screens()]
            on = any(sg.intersected(r).width() >= 120 and sg.intersected(r).height() >= 80 for sg in screens)
            if not on:                              # that screen is gone: the main screen, centred
                sg = QApplication.primaryScreen().availableGeometry()
                r.setSize(r.size().boundedTo(sg.size()))
                r.moveCenter(sg.center())
            self.resize(r.size())
            self.move(r.topLeft())
            self._start_max = bool(g.get("max"))
        except Exception:
            log.exception("restoring the window failed")

    def _layout_changed(self, *_):
        if getattr(self, "_layout_timer", None) is not None and self.isVisible():
            self._layout_timer.start()

    def _layout_cfg(self):
        self._layout_cfg_header()                    # 1.2: the default columns or the crate's own
        if self.isVisible() and not self.isMinimized():
            r = self.normalGeometry() if self.isMaximized() or self.isFullScreen() else self.geometry()
            off = self.pos() - self.geometry().topLeft()        # move() places the frame, not the inside
            if r.width() > 0 and r.height() > 0:
                self.cfg["window"] = {"x": r.x() + off.x(), "y": r.y() + off.y(), "w": r.width(), "h": r.height(),
                                      "max": bool(self.isMaximized())}
            sz = self.main_split.sizes()
            if sz and sz[0] > 40:
                self.cfg["crate_panel_w"] = int(sz[0])

    def _save_layout(self):
        try:
            self._layout_cfg()
            save_config(self.cfg)
        except Exception:
            log.exception("saving the window layout failed")

    def resizeEvent(self, ev):
        super().resizeEvent(ev)
        self._layout_changed()

    def moveEvent(self, ev):
        super().moveEvent(ev)
        self._layout_changed()

    def changeEvent(self, ev):
        super().changeEvent(ev)
        from PySide6.QtCore import QEvent
        if ev.type() == QEvent.Type.WindowStateChange and getattr(self, "_tb", None) is not None:
            self._tb.sync()
            self._tb_margins()
            QTimer.singleShot(0, self._tb_layout)
        if ev.type() == QEvent.Type.ActivationChange and self.isActiveWindow():
            fw = QApplication.focusWidget()
            if fw is None or fw.window() is not self:
                QTimer.singleShot(0, self._focus_list)

    # ---- UI
